const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Original, self-contained envelope and packing-mat illustrations.
export function packingEnvelopeArt(){return '<svg class="pp-envelope" viewBox="0 0 36 26" aria-hidden="true"><rect x="2" y="2" width="32" height="22" rx="3" fill="#fff9e9" stroke="#183f39" stroke-width="2"/><path d="M3 4l15 11L33 4" fill="none" stroke="#397958" stroke-width="2"/><path d="M18 16v6m-3-3q3-5 6-1" fill="none" stroke="#397958"/></svg>';}
export function packingBagArt(count,capacity,{label='Bag'}={}){return `<svg class="pp-bag-art" viewBox="0 0 112 106" role="img" aria-label="${esc(label)}: ${count} of ${capacity} envelopes; ${count===0?'empty':count===capacity?'full':'partly filled'}"><path d="M22 16q34 9 68 0l10 76q-44 18-88 0Z" fill="${count===capacity?'#eaf4ef':'#fff9e9'}" stroke="#183f39" stroke-width="2"/><path d="M24 16q32-13 64 0" fill="none" stroke="#397958" stroke-width="3"/>${Array.from({length:capacity},(_,i)=>{const x=24+(i%3)*23,y=30+Math.floor(i/3)*29;return i<count?`<rect x="${x}" y="${y}" width="20" height="16" rx="2" fill="#e9b84a" stroke="#183f39"/><path d="M${x+1} ${y+2}l9 7 9-7" fill="none" stroke="#183f39"/>`:`<rect x="${x}" y="${y}" width="20" height="16" rx="2" fill="none" stroke="#729584" stroke-dasharray="3 3"/>`;}).join('')}<text x="56" y="98" text-anchor="middle" font-size="12" fill="#183f39">${count} of ${capacity} · ${count===0?'empty':count===capacity?'full':'partly full'}</text></svg>`;}
export function packingLooseArt(n){return `<div class="pp-loose" role="img" aria-label="${n} loose seed envelopes">${Array.from({length:n},()=>packingEnvelopeArt()).join('')}${n===0?'<span>No loose envelopes</span>':''}</div>`;}
export function packingDispatchArt(purpose){return `<svg class="pp-dispatch" viewBox="0 0 540 200" role="img" aria-label="Willow’s courier holds the sealed ${purpose==='kits'?'welcome-kit':'delivery'} bags, ready to go."><path d="M0 164q150-42 270 2t270-5v39H0Z" fill="#eaf4ef"/><path d="M22 48h172l-20 18H22Z" fill="#abc4da"/><path d="M80 65v104M154 65v104" stroke="#397958" stroke-width="5"/><rect x="42" y="84" width="131" height="57" rx="6" fill="#e9b84a" stroke="#183f39" stroke-width="3"/><path d="M46 88l60 35 63-35" fill="none" stroke="#183f39" stroke-width="2"/><ellipse cx="342" cy="139" rx="38" ry="31" fill="#abc4da" stroke="#183f39" stroke-width="2"/><circle cx="342" cy="91" r="25" fill="#fff9e9" stroke="#183f39" stroke-width="2"/><path d="M309 75l31-54 28 54Z" fill="#397958"/><circle cx="334" cy="90" r="2.5" fill="#183f39"/><circle cx="350" cy="90" r="2.5" fill="#183f39"/><path d="M334 102q8 7 16 0M329 166v18m26-18v18M390 160l101-47" fill="none" stroke="#183f39" stroke-width="3"/><path d="M480 112l25-20m-16 24 24-9m-19 15 27 2" stroke="#e9b84a" stroke-width="7"/></svg>`;}
